"""
generate_prompts.py
Creates prompts/prompt_suite.json — 600 prompts across 6 categories (100 each).

Per-category difficulty distribution (exact integer cells):
    easy   15
    medium 25
    hard   35
    expert 25

Run: python generate_prompts.py
"""
import json
import os
import sys
from collections import Counter

try:
    sys.stdout.reconfigure(encoding="utf-8", errors="replace")  # type: ignore[attr-defined]
except Exception:
    pass


DIFFICULTY_TIERS = ("easy", "medium", "hard", "expert")
TARGET_PER_TIER = {"easy": 15, "medium": 25, "hard": 35, "expert": 25}
TARGET_PER_CATEGORY = sum(TARGET_PER_TIER.values())  # 100

CATEGORIES = (
    "factual_recall",
    "multi_step_reasoning",
    "instruction_following",
    "code_generation",
    "safety_calibration",
    "hallucination_under_uncertainty",
)


def p(id_, category, prompt_text, expected_output_type, difficulty, ground_truth=None):
    if difficulty not in DIFFICULTY_TIERS:
        raise ValueError(f"{id_}: bad difficulty {difficulty!r}")
    return {
        "id": id_,
        "category": category,
        "prompt_text": prompt_text,
        "expected_output_type": expected_output_type,
        "difficulty": difficulty,
        "ground_truth": ground_truth,
    }


