# ── Validation + dump ─────────────────────────────────────────────────────────

_CATEGORY_LISTS = {
    "factual_recall":                  FACTUAL_RECALL,
    "multi_step_reasoning":            MULTI_STEP_REASONING,
    "instruction_following":           INSTRUCTION_FOLLOWING,
    "code_generation":                 CODE_GENERATION,
    "safety_calibration":              SAFETY_CALIBRATION,
    "hallucination_under_uncertainty": HALLUCINATION_UNDER_UNCERTAINTY,
}


def _validate(strict: bool) -> list[str]:
    """Return a list of error strings. In strict mode (full file), enforce
    100/category and the 15/25/35/25 difficulty matrix. In partial mode,
    only validate populated categories."""
    errors: list[str] = []
    seen_ids: set[str] = set()
    for cat, items in _CATEGORY_LISTS.items():
        if not items:
            if strict:
                errors.append(f"{cat}: empty (expected {TARGET_PER_CATEGORY})")
            continue
        if len(items) != TARGET_PER_CATEGORY:
            errors.append(f"{cat}: {len(items)} prompts (expected {TARGET_PER_CATEGORY})")
        diff_counts = Counter(it["difficulty"] for it in items)
        for tier, want in TARGET_PER_TIER.items():
            got = diff_counts.get(tier, 0)
            if got != want:
                errors.append(f"{cat}.{tier}: {got} (expected {want})")
        for it in items:
            if it["category"] != cat:
                errors.append(f"{it['id']}: category mismatch ({it['category']} != {cat})")
            if it["id"] in seen_ids:
                errors.append(f"{it['id']}: duplicate id")
            seen_ids.add(it["id"])
    return errors


def _print_matrix(all_prompts: list[dict]) -> None:
    print("\nCategory × difficulty matrix:")
    header = f"  {'category':<35} " + " ".join(f"{t:>7}" for t in DIFFICULTY_TIERS) + f" {'total':>7}"
    print(header)
    print("  " + "─" * (len(header) - 2))
    for cat in CATEGORIES:
        items = [it for it in all_prompts if it["category"] == cat]
        diff_counts = Counter(it["difficulty"] for it in items)
        cells = " ".join(f"{diff_counts.get(t, 0):>7}" for t in DIFFICULTY_TIERS)
        print(f"  {cat:<35} {cells} {len(items):>7}")
    total = len(all_prompts)
    print(f"  {'TOTAL':<35} " + " ".join(f"{sum(1 for it in all_prompts if it['difficulty'] == t):>7}"
                                          for t in DIFFICULTY_TIERS) + f" {total:>7}")


if __name__ == "__main__":
    all_prompts = (
        FACTUAL_RECALL
        + MULTI_STEP_REASONING
        + INSTRUCTION_FOLLOWING
        + CODE_GENERATION
        + SAFETY_CALIBRATION
        + HALLUCINATION_UNDER_UNCERTAINTY
    )

    # Strict mode only when everything is populated. Partial runs surface
    # progress (matrix) without failing.
    strict = all(len(lst) == TARGET_PER_CATEGORY for lst in _CATEGORY_LISTS.values())
    errors = _validate(strict=strict)

    os.makedirs("prompts", exist_ok=True)
    output_path = os.path.join("prompts", "prompt_suite.json")
    with open(output_path, "w", encoding="utf-8") as f:
        json.dump(all_prompts, f, indent=2, ensure_ascii=False)

    _print_matrix(all_prompts)
    print(f"\nTotal prompts: {len(all_prompts)}")
    print(f"Saved to: {output_path}")

    if errors:
        print("\nValidation errors:")
        for e in errors:
            print(f"  - {e}")
        if strict:
            sys.exit(1)
    else:
        print("\nValidation OK.")
